import numpy as np, torch, model
net=model.load(); neg=model.negatives()
uid=np.array(neg['uid']); C=np.array(neg['c'])
M=[107,97,116,1,92,24,63,29,89,8,60]
mi=[int(np.where(uid==u)[0][0]) for u in M]; oi=[i for i in range(len(uid)) if i not in mi]
z=torch.tensor(np.load('sim_z.npy')); c=torch.tensor(np.load('sim_cc.npy')); base=np.load('sim_base.npy')
cs=np.unique(np.load('sim_cc.npy')); n=256
def inany(idx,x):
    r=np.zeros(len(x),bool)
    for i in idx: r|=np.asarray(model.in_basin(i,x))
    return r
def score(x):
    T=np.zeros(len(x),bool);O=np.zeros(len(x),bool);F=np.zeros(len(x),bool)
    for j,cc in enumerate(cs):
        s=slice(j*n,(j+1)*n)
        T[s]=inany([i for i in mi if abs(C[i]-cc)<0.1],x[s])
        O[s]=inany([i for i in oi if abs(C[i]-cc)<0.06],x[s])
        d=np.linalg.norm(x[s][:,None]-base[s][None],axis=2); np.fill_diagonal(d,9)
        F[s]=d.min(1)>0.35
    return T,O,F
T0,O0,F0=score(base)
th=np.radians(155); u=np.array([np.cos(th),np.sin(th)],dtype=np.float32)
def run(k0,k1,wc,T,d):
    x=z.clone(); d=torch.tensor(d,dtype=torch.float32); ut=torch.tensor(u); fired=torch.zeros(len(x),dtype=torch.bool)
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20); v=net.velocity(x,t,c,(),count=False)[0]
        if k0<=k<k1:
            f=(x@ut+wc*c)>T; fired|=f; v=v+f[:,None].float()*d
        x=x-v/20
    return x.numpy(),fired.numpy()
